"""Canonical VERITAS Markets v9.0 UI.

Single-owner dashboard with full decision, portfolio, trade, learning and data-quality views.
No legacy DOM patching or duplicate network loaders.
"""
UI_VERSION = "veritas-ui-v9.0-canonical-rich"

_CANONICAL_HTML = r'''<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>VERITAS Markets</title>
<style>
:root{--bg:#0b1015;--card:#111820;--card2:#0e151c;--line:#26323c;--text:#e8edf2;--muted:#8b97a2;--ok:#59d694;--bad:#ef6767;--warn:#d6b75e}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:13px/1.35 Inter,Arial,sans-serif}
.wrap{max-width:1560px;margin:auto;padding:14px}.header{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}
.brand img{height:54px;max-width:410px;object-fit:contain}.status{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}
.pill{border:1px solid var(--line);border-radius:999px;padding:4px 8px;font-size:9px;color:var(--muted)}
.ok{color:var(--ok)!important}.bad{color:var(--bad)!important}.warn{color:var(--warn)!important}
.grid{display:grid;grid-template-columns:1.1fr 1.1fr .9fr;gap:8px}.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:10px;min-width:0}
.title{font-size:9px;text-transform:uppercase;letter-spacing:.09em;color:var(--muted);margin-bottom:7px}
.full{grid-column:1/-1}.two{grid-column:span 2}.section{margin-top:8px}.msg{font-size:9px;color:var(--muted);padding:5px 0}
.row{display:grid;gap:6px;align-items:center;border-top:1px solid rgba(255,255,255,.045);padding:5px 0;min-width:0}.row:first-child{border-top:0}
.row b{font-size:10px}.row span{font-size:8px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.action{grid-template-columns:62px 58px 42px minmax(110px,1fr) 78px 78px}.asset{grid-template-columns:62px 58px minmax(180px,1fr) 85px}
.tfs{display:grid;grid-template-columns:repeat(6,minmax(33px,1fr));gap:3px}.tf{font-size:7px;text-align:center;padding:3px 2px;border:1px solid var(--line);border-radius:5px;color:var(--muted)}
.matrix-wrap{overflow:auto}.matrix{width:100%;border-collapse:separate;border-spacing:3px}.matrix th{font-size:8px;color:var(--muted);font-weight:500;padding:3px}
.matrix td{padding:0}.cell{width:100%;border:1px solid var(--line);border-radius:6px;background:var(--card2);color:var(--text);padding:5px 3px;cursor:pointer;font-size:8px}
.cell:hover{border-color:#53616d}.cell.sel{outline:1px solid #80909c}.cell small{display:block;font-size:6.5px;color:var(--muted);margin-top:1px}
.detail-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.metric{border:1px solid var(--line);border-radius:8px;padding:6px;min-width:0}
.metric span{display:block;font-size:7px;color:var(--muted)}.metric b{display:block;font-size:10px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.detail-note{margin-top:6px;border-top:1px solid var(--line);padding-top:6px;font-size:8px;color:var(--muted)}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.kpi{border:1px solid var(--line);border-radius:8px;padding:6px}.kpi span{display:block;color:var(--muted);font-size:7px}.kpi b{display:block;margin-top:2px;font-size:12px}
.pf{grid-template-columns:90px 1.1fr 64px 64px 58px 58px}.pos{grid-template-columns:130px 55px minmax(180px,1fr) 90px}
.trade{grid-template-columns:130px 55px 48px 82px 72px 72px 72px 1fr}
.insight-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.insight{border:1px solid var(--line);border-radius:8px;padding:7px;min-width:0}
.insight h4{margin:0 0 5px;font-size:8px;color:var(--muted);font-weight:500;text-transform:uppercase}.insight div{font-size:8px;line-height:1.55}
.scroll{max-height:450px;overflow:auto;padding-right:2px}
@media(max-width:1050px){.grid{grid-template-columns:1fr}.two,.full{grid-column:1}.action{grid-template-columns:56px 52px 38px 1fr}.action .sl,.action .tp{display:none}.detail-grid,.kpis,.insight-grid{grid-template-columns:repeat(2,1fr)}.trade{grid-template-columns:110px 50px 45px 70px 70px 1fr}.trade .gross,.trade .fees{display:none}.brand img{max-width:280px;height:48px}}
</style>
</head>
<body>
<div class="wrap">
  <div class="header">
    <div class="brand"><img src="data:image/webp;base64," alt="VERITAS Markets"></div>
    <div class="status">
      <span class="pill" id="sys">SYSTEM —</span>
      <span class="pill" id="db">DB —</span>
      <span class="pill" id="cells">DATA —</span>
      <span class="pill" id="stamp">—</span>
    </div>
  </div>

  <div class="grid">
    <div class="card">
      <div class="title">Что делать сейчас</div>
      <div id="actions"><div class="msg">Загрузка сигналов…</div></div>
    </div>

    <div class="card two">
      <div class="title">Общий взгляд по активам</div>
      <div id="assets"><div class="msg">Загрузка рынка…</div></div>
    </div>

    <div class="card two section">
      <div class="title">Матрица сигналов · 7 активов × 6 таймфреймов</div>
      <div class="matrix-wrap"><table class="matrix"><thead><tr><th>Актив</th><th>5м</th><th>1ч</th><th>4ч</th><th>1д</th><th>3д</th><th>7д</th></tr></thead><tbody id="matrixBody"></tbody></table></div>
    </div>

    <div class="card section">
      <div class="title">Разбор выбранного сигнала</div>
      <div id="detail"><div class="msg">Нажми любую ячейку матрицы.</div></div>
    </div>

    <div class="card full section">
      <div class="title">Портфели</div>
      <div class="kpis">
        <div class="kpi"><span>Портфелей</span><b id="pfCount">—</b></div>
        <div class="kpi"><span>Открытых позиций</span><b id="openCount">—</b></div>
        <div class="kpi"><span>Лучшая доходность</span><b id="bestRet">—</b></div>
        <div class="kpi"><span>Макс. просадка</span><b id="maxDD">—</b></div>
      </div>
      <div id="portfolios" style="margin-top:6px"><div class="msg">Загрузка портфелей…</div></div>
    </div>

    <div class="card full section">
      <div class="title">Открытые позиции</div>
      <div id="positions"><div class="msg">Загрузка позиций…</div></div>
    </div>

    <div class="card full section">
      <div class="title">Последние сделки</div>
      <div id="trades" class="scroll"><div class="msg">Загрузка журнала…</div></div>
    </div>

    <div class="card full section">
      <div class="title">Обучение · качество данных · горизонты · макро</div>
      <div class="insight-grid">
        <div class="insight"><h4>Обучение</h4><div id="learning">Загрузка…</div></div>
        <div class="insight"><h4>Качество данных</h4><div id="quality">Загрузка…</div></div>
        <div class="insight"><h4>Целостность горизонтов</h4><div id="horizon">Загрузка…</div></div>
        <div class="insight"><h4>Макро</h4><div id="macro">Загрузка…</div></div>
      </div>
    </div>
  </div>
</div>

<script>
(function(){
'use strict';
const AS=['BTC','ETH','NQ','BRENT','GOLD','MOEX','CNYRUBF'], TF=['5m','1h','4h','1d','3d','7d'];
const st={signals:null,portfolios:null,trades:null,health:null,learning:null,quality:null,horizon:null,macro:null,busy:{},selected:null};
const $=id=>document.getElementById(id);
const esc=v=>String(v==null?'—':v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const lab=a=>a==='NQ'?'NDXf':a==='CNYRUBF'?'CNYRUBf':a;
const dir=x=>String((x&&x.research_decision)||(x&&x.decision)||'NO_TRADE');
const cls=d=>d==='LONG'?'ok':d==='SHORT'?'bad':'warn', ar=d=>d==='LONG'?'↑':d==='SHORT'?'↓':'→';
const n=(v,d=2)=>{v=Number(v);return Number.isFinite(v)?v.toLocaleString('ru-RU',{maximumFractionDigits:d}):'—'};
const rub=v=>{v=Number(v);return Number.isFinite(v)?v.toLocaleString('ru-RU',{maximumFractionDigits:0})+' ₽':'—'};
const pct=v=>{v=Number(v);return Number.isFinite(v)?v.toFixed(2)+'%':'—'};
const bool=v=>v===true?'ДА':v===false?'НЕТ':'—';

async function get(key,url,ms){
  if(st.busy[key])return null;st.busy[key]=true;
  const ctl=new AbortController(),tm=setTimeout(()=>ctl.abort(),ms);
  try{const r=await fetch(url,{cache:'no-store',signal:ctl.signal});if(!r.ok)throw new Error('HTTP '+r.status);return await r.json()}
  catch(e){return null}finally{clearTimeout(tm);st.busy[key]=false}
}

function renderHealth(){
  const h=st.health||{};
  $('sys').textContent=h.ok?'SYSTEM ONLINE':'SYSTEM STARTING';$('sys').className='pill '+(h.ok?'ok':'warn');
  $('db').textContent=h.bootstrap_ready?'DB READY':'DB INIT';$('db').className='pill '+(h.bootstrap_ready?'ok':'warn');
}

function signalMap(){const m={};((st.signals&&st.signals.signals)||[]).forEach(x=>{if(x&&x.asset&&x.horizon)m[x.asset+'|'+x.horizon]=x});return m}

function renderSignals(){
  const d=st.signals||{}, rows=Array.isArray(d.signals)?d.signals:[], map=signalMap();
  $('cells').textContent='DATA '+rows.length+'/42';$('cells').className='pill '+(rows.length>=42?'ok':rows.length?'warn':'bad');
  $('stamp').textContent=d.at?new Date(d.at).toLocaleTimeString():'—';

  const rank=x=>{const D=dir(x);if(!['LONG','SHORT'].includes(D))return-999;return(x.plan_eligible===false?0:2)+4*Number(x.horizon_structure_score||0)+2*Number(x.confidence||0)+Math.min(Number(x.expected_to_stop_ratio||0),3)+.2*Number(x.independent_evidence_families||0)};
  const best=rows.filter(x=>['LONG','SHORT'].includes(dir(x))).sort((a,b)=>rank(b)-rank(a)).slice(0,5);
  $('actions').innerHTML=best.length?best.map(x=>'<div class="row action"><b>'+lab(x.asset)+'</b><b class="'+cls(dir(x))+'">'+ar(dir(x))+' '+dir(x)+'</b><span>'+x.horizon+'</span><span>'+esc(x.entry_quality||x.plan_reason||x.regime||'—')+' · R/R '+(x.expected_to_stop_ratio==null?'—':Number(x.expected_to_stop_ratio).toFixed(2))+'</span><span class="sl">SL '+n(x.stop_price,4)+'</span><span class="tp">TP '+n(x.target_price,4)+'</span></div>').join(''):'<div class="msg">Сильных направленных идей сейчас нет.</div>';

  $('assets').innerHTML=AS.map(a=>{const xs=TF.map(tf=>map[a+'|'+tf]).filter(Boolean),ds=xs.map(dir),ln=ds.filter(x=>x==='LONG').length,sn=ds.filter(x=>x==='SHORT').length,D=ln>sn?'LONG':sn>ln?'SHORT':'WAIT',p=(map[a+'|5m']||xs[0]||{}).price;return'<div class="row asset"><b>'+lab(a)+'</b><b class="'+cls(D)+'">'+ar(D)+' '+D+'</b><span>'+TF.map(tf=>{const x=map[a+'|'+tf];return tf+':' +(x?ar(dir(x)):'—')}).join(' · ')+'</span><span style="text-align:right">'+n(p,4)+'</span></div>'}).join('');

  $('matrixBody').innerHTML=AS.map(a=>'<tr><th>'+lab(a)+'</th>'+TF.map(tf=>{const x=map[a+'|'+tf];if(!x)return'<td><button class="cell">—</button></td>';const D=dir(x),conf=100*Number(x.confidence||0);return'<td><button class="cell '+cls(D)+'" data-k="'+a+'|'+tf+'">'+ar(D)+' '+D.replace('NO_TRADE','WAIT')+'<small>'+conf.toFixed(0)+'%</small></button></td>'}).join('')+'</tr>').join('');
  document.querySelectorAll('.cell[data-k]').forEach(b=>b.onclick=()=>selectSignal(b.dataset.k));
  if(!st.selected&&rows.length){const x=best[0]||rows[0];st.selected=x.asset+'|'+x.horizon}
  if(st.selected)selectSignal(st.selected,false);
}

function selectSignal(k,scroll=false){
  st.selected=k;document.querySelectorAll('.cell').forEach(x=>x.classList.toggle('sel',x.dataset.k===k));
  const x=signalMap()[k];if(!x){$('detail').innerHTML='<div class="msg">Нет данных.</div>';return}
  const sl=x.structural_levels||{}, plan=x.trade_plan||{}, D=dir(x);
  const items=[
    ['Актив',lab(x.asset)],['ТФ',x.horizon],['Направление',D],['Цена',n(x.price,4)],
    ['Confidence',x.confidence==null?'—':(100*Number(x.confidence)).toFixed(1)+'%'],['Structure',n(x.horizon_structure_score,3)],['Regime',x.regime],['Stage',x.decision_stage],
    ['Entry quality',x.entry_quality],['Подтверждения',x.independent_evidence_families],['Execution',bool(x.execution_eligible)],['Source gate',bool(x.source_gate_pass)],
    ['SL',n(x.stop_price??plan.stop_price,4)],['TP',n(x.target_price??plan.target_price,4)],['R/R',n(x.expected_to_stop_ratio??plan.expected_to_stop_ratio,2)],['Expected move',x.expected_move_pct==null?'—':(100*Number(x.expected_move_pct)).toFixed(2)+'%'],
    ['Support',n(sl.support,4)],['Resistance',n(sl.resistance,4)],['SMA18',n(sl.sma18,4)],['SMA50',n(sl.sma50,4)]
  ];
  $('detail').innerHTML='<div class="detail-grid">'+items.map(([a,b])=>'<div class="metric"><span>'+a+'</span><b class="'+(a==='Направление'?cls(D):'')+'">'+esc(b)+'</b></div>').join('')+'</div><div class="detail-note">Причина: <b>'+esc(x.plan_reason||plan.reason||'—')+'</b><br>Execution reason: '+esc(x.execution_reason||'—')+' · Market open: '+bool(x.market_open)+' · stale: '+bool(x.snapshot_stale)+'</div>';
  if(scroll)$('detail').scrollIntoView({behavior:'smooth',block:'nearest'});
}

function renderPortfolios(){
  const d=st.portfolios||{},ps=Array.isArray(d.portfolios)?d.portfolios:[],positions=[];
  ps.forEach(p=>(p.positions||[]).forEach(z=>positions.push(Object.assign({portfolio:p.name},z))));
  $('pfCount').textContent=ps.length+'/4';$('openCount').textContent=positions.length;
  const rets=ps.map(p=>Number(p.total_return_pct!=null?p.total_return_pct:((p.latest||{}).total_return_pct))).filter(Number.isFinite);
  const dds=ps.map(p=>Number(p.drawdown_pct!=null?p.drawdown_pct:(((p.latest||{}).drawdown!=null)?100*Number((p.latest||{}).drawdown):NaN))).filter(Number.isFinite);
  $('bestRet').textContent=rets.length?Math.max(...rets).toFixed(2)+'%':'—';$('maxDD').textContent=dds.length?Math.max(...dds).toFixed(2)+'%':'—';
  $('portfolios').innerHTML=ps.length?ps.map(p=>{const l=p.latest||p,nav=l.nav_rub??p.nav_rub,usd=l.nav_usd??p.nav_usd,ret=p.total_return_pct??l.total_return_pct,dd=p.drawdown_pct??(l.drawdown!=null?100*Number(l.drawdown):null),gross=l.gross_leverage??p.gross_leverage,net=l.net_exposure??p.net_exposure,cash=l.cash_equivalent_fraction??p.cash_equivalent_fraction,wr=p.win_rate==null?'—':(100*Number(p.win_rate)).toFixed(1)+'%';return'<div class="row pf"><b>'+esc(p.name)+'</b><span>NAV '+rub(nav)+' · $'+n(usd,0)+'</span><b class="'+(Number(ret||0)>=0?'ok':'bad')+'">'+pct(ret)+'</b><span>DD '+pct(dd)+'</span><span>G '+n(gross,2)+'×</span><span>W '+wr+'</span><span style="display:none">'+n(net,2)+' '+n(cash,2)+'</span></div>'}).join(''):'<div class="msg warn">Портфели пока не получены.</div>';
  $('positions').innerHTML=positions.length?positions.map(z=>'<div class="row pos"><b>'+esc(z.portfolio)+' · '+lab(z.asset)+'</b><b class="'+(z.direction==='LONG'?'ok':'bad')+'">'+esc(z.direction)+'</b><span>'+esc(z.horizon||'—')+' · вход '+n(z.avg_entry_price,4)+' · текущая '+n(z.last_price,4)+' · SL '+n(z.stop_price,4)+' · TP '+n(z.take_price??z.target_price,4)+' · объём '+rub(z.notional_rub)+'</span><b class="'+(Number(z.unrealized_pnl_rub||0)>=0?'ok':'bad')+'">'+rub(z.unrealized_pnl_rub)+'</b></div>').join(''):'<div class="msg">Открытых позиций нет.</div>';
}

function renderTrades(){
  const rows=Array.isArray(st.trades&&st.trades.trades)?st.trades.trades:[];
  $('trades').innerHTML=rows.length?rows.slice(0,80).map(t=>{const net=t.net_pnl_rub,g=t.gross_pnl_rub,fees=t.fees_rub,fund=t.funding_rub,p=t.payload||{},held=t.holding_duration_seconds??t.held_seconds;return'<div class="row trade"><b>'+esc(t.portfolio_name)+' · '+lab(t.asset)+'</b><span>'+esc(t.direction)+'</span><span>'+esc(t.horizon||'—')+'</span><span>'+esc(t.exit_reason||p.exit_reason||t.status||'—')+'</span><span class="gross">G '+rub(g)+'</span><span class="fees">C '+rub(Number(fees||0)+Number(fund||0))+'</span><b class="'+(Number(net||0)>=0?'ok':'bad')+'">'+rub(net)+'</b><span>'+esc(p.learning_label||t.learning_label||'—')+' · '+(held==null?'—':held>=3600?(held/3600).toFixed(1)+'ч':Math.max(1,Math.round(held/60))+'м')+'</span></div>'}).join(''):'<div class="msg">Сделки пока не получены.</div>';
}

function flatSummary(obj,max=8){
  if(!obj||typeof obj!=='object')return'—';
  const out=[];function walk(o,p='',d=0){if(out.length>=max||d>2||!o||typeof o!=='object')return;for(const [k,v] of Object.entries(o)){if(out.length>=max)break;const key=p?p+'.'+k:k;if(v==null)continue;if(typeof v==='string'||typeof v==='number'||typeof v==='boolean')out.push('<b>'+esc(key)+'</b>: '+esc(v));else if(Array.isArray(v)&&v.length<=8&&v.every(x=>['string','number','boolean'].includes(typeof x)))out.push('<b>'+esc(key)+'</b>: '+esc(v.join(', ')));else walk(v,key,d+1)}}walk(obj);return out.join('<br>')||'—'
}
function renderInsights(){
  $('learning').innerHTML=flatSummary(st.learning,10);
  $('quality').innerHTML=flatSummary(st.quality,10);
  $('horizon').innerHTML=flatSummary(st.horizon,10);
  $('macro').innerHTML=flatSummary(st.macro,10);
}

async function loadHealth(){const d=await get('health','/healthz',3000);if(d){st.health=d;renderHealth()}}
async function loadSignals(){const d=await get('signals','/api/v1/signals',6000);if(d){st.signals=d;renderSignals()}}
async function loadPortfolios(){const d=await get('portfolios','/api/v1/paper-portfolios',6000);if(d){st.portfolios=d;renderPortfolios()}}
async function loadTrades(){const d=await get('trades','/api/v1/portfolio-trades',8000);if(d){st.trades=d;renderTrades()}}
async function loadInsights(){
  const [l,q,h,m]=await Promise.all([
    get('learning','/api/v1/learning-progress',6000),
    get('quality','/api/v1/data-quality',6000),
    get('horizon','/api/v1/horizon-integrity',6000),
    get('macro','/api/v1/macro',7000)
  ]);
  if(l)st.learning=l;if(q)st.quality=q;if(h)st.horizon=h;if(m)st.macro=m;renderInsights()
}
function start(){loadHealth();loadSignals();loadPortfolios();loadTrades();setTimeout(loadInsights,1200);setInterval(loadHealth,30000);setInterval(loadSignals,30000);setInterval(loadPortfolios,30000);setInterval(loadTrades,60000);setInterval(loadInsights,120000)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
</script>
</body>
</html>'''

def apply_v90_ui(html):
    print('{"event":"V90_CANONICAL_RICH_UI","status":"installed"}', flush=True)
    return _CANONICAL_HTML
